function read<T>(key:string,fallback:T):T{try{const v=localStorage.getItem('bloom_'+key);return v?JSON.parse(v):fallback}catch{return fallback}}
const SYNC_API=(import.meta.env.VITE_API_URL||'').replace(/\/$/,'');
async function syncRequest(path:string,token:string,options?:RequestInit){
 if(!SYNC_API)throw new Error('Chưa cấu hình VITE_API_URL khi build frontend.');
 const response=await fetch(`${SYNC_API}/api/sync/${path}`,{...options,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})}});
 const data=await response.json().catch(()=>({}));
 if(!response.ok)throw new Error(response.status===409?'Dữ liệu đã được máy khác cập nhật. Hãy tải bản mới và kiểm tra thay đổi trước khi lưu.':(data.message||`Lỗi API ${response.status}`));
 return data;
}
