 const [page,setPage]=useState('Tổng quan'),[products,setProducts]=useState<Product[]>(()=>read('products',seedProducts)),[customers,setCustomers]=useState<Customer[]>(()=>read('customers',[{id:'C001',name:'Ngọc Anh',phone:'0901234567',note:'Thích hoa hồng'},{id:'C002',name:'Minh Khang',phone:'0912345678',note:''},{id:'C003',name:'Thu Hà',phone:'0987654321',note:'Giao buổi sáng'}])),[orders,setOrders]=useState<Order[]>(()=>read('orders',initialOrders)),[store,setStore]=useState<Store>(()=>read('store',{name:'Nàng Hoa',phone:'0900 123 456',address:'941 Phan Văn Trị, Hạnh Thông, Gò Vấp',bankId:'970422',bankName:'MB Bank',accountNo:'0123456789',accountName:'NGUYEN VAN A'}));
